import math

def exact(n, base=1):
    """T(n) = 2T(n/2) + n by direct recursion, T(1) = base."""
    if n == 1:
        return base
    return 2 * exact(n // 2, base) + n

def tree_sum(n, base=1):
    """Recursion-tree method: sum the cost of every level explicitly."""
    total, size, nodes = 0, n, 1
    while size > 1:
        total += nodes * size      # level cost = nodes * per-node work (n/2^i)
        nodes *= 2
        size //= 2
    total += nodes * base          # the final Theta(1) leaves
    return total

def closed_form(n, base=1):
    return n * math.log2(n) + base * n

for k in range(0, 6):
    n = 2 ** k
    print(f"n={n:3d}  exact={exact(n):5d}  tree_sum={tree_sum(n):5d}  closed_form={closed_form(n):7.1f}")
